__kernel void process(__global const float* in_pos, __global const float* in_col, int in_count, __global float* out_pos, __global float* out_col, __global int* out_count, int max_vertices) {
    int id = get_global_id(0);
    if (id == 0) {
        float size = chf("Size", 1.0f);
        float center_x = 0.0f;
        float center_y = 0.0f;
        float center_z = 0.0f;
        int divs = 16;
        float half_size = size * 0.5f;
        float step = size / (float)divs;
        float inv = size > 0.0f ? 1.0f / size : 0.0f;
        int count = 0;
        for (int i = 0; i < divs; i++) {
            float x0 = -half_size + (float)i * step;
            float x1 = x0 + step;
            for (int j = 0; j < divs; j++) {
                float z0 = -half_size + (float)j * step;
                float z1 = z0 + step;
                float px[6] = {x0, x1, x1, x0, x0, x1};
                float pz[6] = {z0, z1, z0, z0, z1, z1};
                for (int v = 0; v < 6; v++) {
                    int idx = count++;
                    if (idx < max_vertices) {
                        out_pos[idx * 3 + 0] = center_x + px[v];
                        out_pos[idx * 3 + 1] = center_y;
                        out_pos[idx * 3 + 2] = center_z + pz[v];
                        float fx = (px[v] + half_size) * inv;
                        float fz = (pz[v] + half_size) * inv;
                        out_col[idx * 3 + 0] = 0.35f + fx * 0.35f;
                        out_col[idx * 3 + 1] = 0.45f + fz * 0.35f;
                        out_col[idx * 3 + 2] = 0.85f;
                    }
                }
            }
        }
        *out_count = count;
    }
}
